UPDATE articles SET body='{"id":"brain-computer-interface","revision":2,"current":{"id":"brain-computer-interface","schemaVersion":1,"values":{"term":"brain–computer interface","equivalent":"интерфейс мозг–компьютер","abbreviation":"BCI","category":"Интерфейсы","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Система коммуникации или управления, которая преобразует сигналы активности мозга в команды внешнему устройству, предоставляя канал взаимодействия, не зависящий от мышечного управления."},{"type":"text","text":" [1]","marks":[{"type":"source_ref","attrs":{"id":"source-1"}}]}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Английский многокомпонентный термин объединяет brain и computer как участников взаимодействия. Русский эквивалент сохраняет эту структуру. Аббревиатура "},{"type":"text","text":"BCI","marks":[{"type":"term_ref","attrs":{"id":"brain-computer-interface"}}]},{"type":"text","text":" обозначает полное выражение, а не отдельный концепт. В популярном объяснении термин может сближаться с метафорой «чтения мыслей»: такое употребление требует анализа контекста и не должно автоматически становиться новым значением термина."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Представьте, что сигнал мозга становится командой для курсора — это и есть интерфейс мозг–компьютер."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Объяснительная парафраза через конкретный сценарий управления. Пример создан для демонстрации интерфейса; это не цитата из подкаста."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"Wolpaw et al. · Brain-computer interfaces for communication and control (2002)","url":"https://pubmed.ncbi.nlm.nih.gov/12048038/","note":"Определение выше — редакторский пересказ, не дословная цитата."},{"id":"source-2","title":"Wolpaw, Millán & Ramsey · Definitions and principles (2020)","url":"https://pubmed.ncbi.nlm.nih.gov/32164849/","note":"Дополнительный материал о принципах BCI."}],"related":["electroencephalography","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"published":{"id":"brain-computer-interface","schemaVersion":1,"values":{"term":"brain–computer interface","equivalent":"интерфейс мозг–компьютер","abbreviation":"BCI","category":"Интерфейсы","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Система коммуникации или управления, которая преобразует сигналы активности мозга в команды внешнему устройству, предоставляя канал взаимодействия, не зависящий от мышечного управления."},{"type":"text","text":" [1]","marks":[{"type":"source_ref","attrs":{"id":"source-1"}}]}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Английский многокомпонентный термин объединяет brain и computer как участников взаимодействия. Русский эквивалент сохраняет эту структуру. Аббревиатура "},{"type":"text","text":"BCI","marks":[{"type":"term_ref","attrs":{"id":"brain-computer-interface"}}]},{"type":"text","text":" обозначает полное выражение, а не отдельный концепт. В популярном объяснении термин может сближаться с метафорой «чтения мыслей»: такое употребление требует анализа контекста и не должно автоматически становиться новым значением термина."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Представьте, что сигнал мозга становится командой для курсора — это и есть интерфейс мозг–компьютер."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Объяснительная парафраза через конкретный сценарий управления. Пример создан для демонстрации интерфейса; это не цитата из подкаста."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"Wolpaw et al. · Brain-computer interfaces for communication and control (2002)","url":"https://pubmed.ncbi.nlm.nih.gov/12048038/","note":"Определение выше — редакторский пересказ, не дословная цитата."},{"id":"source-2","title":"Wolpaw, Millán & Ramsey · Definitions and principles (2020)","url":"https://pubmed.ncbi.nlm.nih.gov/32164849/","note":"Дополнительный материал о принципах BCI."}],"related":["electroencephalography","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"publishedRevision":2,"updatedAt":"2026-10-09T12:00:00.000Z"}' WHERE id='brain-computer-interface';
