UPDATE articles SET body='{"id":"electroencephalography","revision":2,"current":{"id":"electroencephalography","schemaVersion":1,"values":{"term":"electroencephalography","equivalent":"электроэнцефалография","abbreviation":"EEG","category":"Методы регистрации","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод регистрации электрической активности мозга с помощью электродов, размещённых на коже головы."},{"type":"text","text":" [1]","marks":[{"type":"source_ref","attrs":{"id":"source-1"}}]}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В статье различаются метод — electroencephalography — и результат регистрации — electroencephalogram. В англоязычном дискурсе сокращение "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":" может обозначать и метод, и запись: интерпретацию следует устанавливать по контексту. Русское ЭЭГ также требует контекстного уточнения. Применение "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":" в "},{"type":"text","text":"BCI","marks":[{"type":"term_ref","attrs":{"id":"brain-computer-interface"}}]},{"type":"text","text":" не делает эти термины синонимами: первый обозначает способ регистрации, второй — систему взаимодействия."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мы записали EEG, а затем посмотрели, как менялся сигнал во время задания."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический пример: «EEG» здесь обозначает запись. Серия, говорящий и таймкод отсутствуют, поскольку источник не засвидетельствован."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NINDS · Neurological Diagnostic Tests and Procedures","url":"https://www.ninds.nih.gov/health-information/disorders/neurological-diagnostic-tests-and-procedures","note":"Редакторский пересказ раздела Electroencephalography."}],"related":["brain-computer-interface","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"published":{"id":"electroencephalography","schemaVersion":1,"values":{"term":"electroencephalography","equivalent":"электроэнцефалография","abbreviation":"EEG","category":"Методы регистрации","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод регистрации электрической активности мозга с помощью электродов, размещённых на коже головы."},{"type":"text","text":" [1]","marks":[{"type":"source_ref","attrs":{"id":"source-1"}}]}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В статье различаются метод — electroencephalography — и результат регистрации — electroencephalogram. В англоязычном дискурсе сокращение "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":" может обозначать и метод, и запись: интерпретацию следует устанавливать по контексту. Русское ЭЭГ также требует контекстного уточнения. Применение "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":" в "},{"type":"text","text":"BCI","marks":[{"type":"term_ref","attrs":{"id":"brain-computer-interface"}}]},{"type":"text","text":" не делает эти термины синонимами: первый обозначает способ регистрации, второй — систему взаимодействия."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мы записали EEG, а затем посмотрели, как менялся сигнал во время задания."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический пример: «EEG» здесь обозначает запись. Серия, говорящий и таймкод отсутствуют, поскольку источник не засвидетельствован."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NINDS · Neurological Diagnostic Tests and Procedures","url":"https://www.ninds.nih.gov/health-information/disorders/neurological-diagnostic-tests-and-procedures","note":"Редакторский пересказ раздела Electroencephalography."}],"related":["brain-computer-interface","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"publishedRevision":2,"updatedAt":"2026-10-09T12:00:00.000Z"}' WHERE id='electroencephalography';
INSERT OR IGNORE INTO revisions(article_id,revision,body) VALUES('electroencephalography',2,'{"revision":2,"document":{"id":"electroencephalography","schemaVersion":1,"values":{"term":"electroencephalography","equivalent":"электроэнцефалография","abbreviation":"EEG","category":"Методы регистрации","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод регистрации электрической активности мозга с помощью электродов, размещённых на коже головы."},{"type":"text","text":" [1]","marks":[{"type":"source_ref","attrs":{"id":"source-1"}}]}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В статье различаются метод — electroencephalography — и результат регистрации — electroencephalogram. В англоязычном дискурсе сокращение "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":" может обозначать и метод, и запись: интерпретацию следует устанавливать по контексту. Русское ЭЭГ также требует контекстного уточнения. Применение "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":" в "},{"type":"text","text":"BCI","marks":[{"type":"term_ref","attrs":{"id":"brain-computer-interface"}}]},{"type":"text","text":" не делает эти термины синонимами: первый обозначает способ регистрации, второй — систему взаимодействия."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мы записали EEG, а затем посмотрели, как менялся сигнал во время задания."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический пример: «EEG» здесь обозначает запись. Серия, говорящий и таймкод отсутствуют, поскольку источник не засвидетельствован."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NINDS · Neurological Diagnostic Tests and Procedures","url":"https://www.ninds.nih.gov/health-information/disorders/neurological-diagnostic-tests-and-procedures","note":"Редакторский пересказ раздела Electroencephalography."}],"related":["brain-computer-interface","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"actor":"sample-import","origin":"import","time":"2026-10-09T12:00:00.000Z","action":"add-source-and-term-links"}');
UPDATE articles SET body='{"id":"neurofeedback","revision":2,"current":{"id":"neurofeedback","schemaVersion":1,"values":{"term":"neurofeedback","equivalent":"нейрообратная связь","abbreviation":"","category":"Практики саморегуляции","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод обучения саморегуляции мозговой активности через обратную связь, предоставляемую человеку на основе измеряемых сигналов."},{"type":"text","text":" [1]","marks":[{"type":"source_ref","attrs":{"id":"source-1"}}]}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сложное слово neurofeedback сочетает указание на нейронную активность с понятием обратной связи. В русскоязычных материалах встречаются как калька, так и заимствование. "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":"-based neurofeedback обозначает частный случай: не вся нейрообратная связь основана на "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":". Различайте описание метода, обещание эффекта и исследовательскую интерпретацию."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"На экране меняется индикатор, а участник пробует научиться влиять на него, наблюдая обратную связь."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический учебный пример объяснения через интерфейс. Это не доказательство эффективности метода и не реальный подкастовый фрагмент."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NLM MeSH · Neurofeedback","url":"https://www.ncbi.nlm.nih.gov/mesh/D058765","note":"Редакторский пересказ определения контролируемого словаря."},{"id":"source-2","title":"Sitaram et al. · Closed-loop brain training: the science of neurofeedback","url":"https://www.nature.com/articles/nrn.2016.164","note":"Обзор разных методов регистрации и принципов обратной связи."}],"related":["electroencephalography","brain-computer-interface"],"externalMappings":[],"sampleRecord":true}},"published":{"id":"neurofeedback","schemaVersion":1,"values":{"term":"neurofeedback","equivalent":"нейрообратная связь","abbreviation":"","category":"Практики саморегуляции","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод обучения саморегуляции мозговой активности через обратную связь, предоставляемую человеку на основе измеряемых сигналов."},{"type":"text","text":" [1]","marks":[{"type":"source_ref","attrs":{"id":"source-1"}}]}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сложное слово neurofeedback сочетает указание на нейронную активность с понятием обратной связи. В русскоязычных материалах встречаются как калька, так и заимствование. "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":"-based neurofeedback обозначает частный случай: не вся нейрообратная связь основана на "},{"type":"text","text":"EEG","marks":[{"type":"term_ref","attrs":{"id":"electroencephalography"}}]},{"type":"text","text":". Различайте описание метода, обещание эффекта и исследовательскую интерпретацию."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"На экране меняется индикатор, а участник пробует научиться влиять на него, наблюдая обратную связь."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический учебный пример объяснения через интерфейс. Это не доказательство эффективности метода и не реальный подкастовый фрагмент."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NLM MeSH · Neurofeedback","url":"https://www.ncbi.nlm.nih.gov/mesh/D058765","note":"Редакторский пересказ определения контролируемого словаря."},{"id":"source-2","title":"Sitaram et al. · Closed-loop brain training: the science of neurofeedback","url":"https://www.nature.com/articles/nrn.2016.164","note":"Обзор разных методов регистрации и принципов обратной связи."}],"related":["electroencephalography","brain-computer-interface"],"externalMappings":[],"sampleRecord":true}},"publishedRevision":2,"updatedAt":"2026-10-09T12:00:00.000Z"}' WHERE id='neurofeedback';
